import { useEffect, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:5000");

function PatientDashboard() {

  const [queues, setQueues] = useState([]);
  const [form, setForm] = useState({
    patientName: "",
    doctor: "",
    department: "",
    date: ""
  });

  // GET DATA
  const fetchQueues = async () => {
    const res = await fetch("http://localhost:5000/api/queue/all");
    const data = await res.json();
    setQueues(data);
  };

  // LOAD + SOCKET LISTENER
  useEffect(() => {
    fetchQueues();

    socket.on("queueUpdated", () => {
      fetchQueues(); // REAL TIME UPDATE
    });

    socket.on("notification", (msg) => {
      alert(msg);
    });

    return () => {
      socket.off();
    };
  }, []);

  // BOOK OP
  const bookOP = async () => {
    await fetch("http://localhost:5000/api/queue/add", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(form)
    });

    setForm({
      patientName: "",
      doctor: "",
      department: "",
      date: ""
    });
  };

  // JOIN QUEUE
  const joinQueue = async (id) => {
    const res = await fetch(`http://localhost:5000/api/queue/join/${id}`, {
      method: "PUT"
    });

    const data = await res.json();

    if (!res.ok) {
      alert(data);
    }
  };

  return (
    <div style={{ padding: 30 }}>

      <h2>👤 Patient Dashboard</h2>

      {/* BOOK OP */}
      <div>
        <input placeholder="Name"
          onChange={(e) => setForm({ ...form, patientName: e.target.value })} />

        <input placeholder="Doctor"
          onChange={(e) => setForm({ ...form, doctor: e.target.value })} />

        <input placeholder="Department"
          onChange={(e) => setForm({ ...form, department: e.target.value })} />

        <input type="date"
          onChange={(e) => setForm({ ...form, date: e.target.value })} />

        <button onClick={bookOP}>Book OP</button>
      </div>

      <hr />

      {/* LIST */}
      {queues.map((q) => (
        <div key={q._id} style={{ border: "1px solid black", margin: 10, padding: 10 }}>

          <h3>Token: {q.tokenNumber}</h3>
          <p>Status: {q.status}</p>

          {q.status === "Confirmed" && (
            <button onClick={() => joinQueue(q._id)}>
              Join Queue
            </button>
          )}

        </div>
      ))}

    </div>
  );
}

export default PatientDashboard;
